try:
    print('>>> x = 2.3456')
    print('>>> y = range(0)')
    print('>>> x %= y')
    print('>>> x')
    x = 2.3456
    y = range(0)
    x %= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
